inventory:
def test_restock_missing():
    assert candidate.restock({}, 'x', 4) == {'x': 4}


def test_restock_existing():
    assert candidate.restock({'x': 1}, 'x', 4) == {'x': 5}


def test_restock_does_not_mutate():
    levels = {'x': 1}
    candidate.restock(levels, 'y', 2)
    assert levels == {'x': 1}


def test_total_units_many():
    assert candidate.total_units({'a': 2, 'b': 3, 'c': 4}) == 9


def test_total_units_empty():
    assert candidate.total_units({}) == 0


def test_parse_quantity_negative():
    try:
        candidate.parse_quantity('-1')
    except ValueError:
        return
    raise AssertionError('negative quantity accepted')

textstats:
def test_word_count_empty():
    assert candidate.word_count('') == 0


def test_word_count_whitespace_mix():
    assert candidate.word_count(' one\ttwo  three\n') == 3


def test_average_empty():
    assert candidate.average_word_length('   ') == 0.0


def test_average_three():
    assert candidate.average_word_length('a bb ccc') == 2.0


def test_longest_first():
    assert candidate.longest_word('ab cd e') == 'ab'

intervals:
def test_overlap_touch_reverse():
    assert candidate.overlaps((3, 5), (1, 3)) is True


def test_disjoint():
    assert candidate.overlaps((1, 2), (3, 4)) is False


def test_merge_nested_unsorted():
    assert candidate.merge([(4, 9), (0, 1), (5, 6)]) == [(0, 1), (4, 9)]


def test_merge_touching():
    assert candidate.merge([(3, 4), (1, 3)]) == [(1, 4)]


def test_total_length_unsorted():
    assert candidate.total_length([(5, 7), (0, 2), (1, 3)]) == 5
